import {Game} from './engine.js';
import {Renderer} from './renderer.js';
import {Input} from './input.js';
import {AudioSystem} from './audio.js';
import {RARITIES} from './data.js';
import {getEncounterPresentation} from './encounters.js';
const $=id=>document.getElementById(id),overlay=$('overlay'),audio=new AudioSystem();
let best=0;try{best=Number(localStorage.getItem('emberfall-best'))||0}catch{}
let game,input,announceTimeout;const format=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function modal(html){overlay.innerHTML=html;const button=overlay.querySelector('button');if(button)button.focus({preventScroll:true});if(input)input.reset()}
function announce(text){$('announcement').textContent=text;$('announcement').style.opacity=1;clearTimeout(announceTimeout);announceTimeout=setTimeout(()=>$('announcement').style.opacity=0,3500)}
function onEvent(type,data){if(type==='sound'){audio.play(data);return}if(type==='reset')return;if(type==='levelup')showChoices(data);if(type==='upgrade'){if(game.state==='playing')overlay.innerHTML='';updateSkills()}if(type==='synergy')announce(`共鳴覺醒 · ${data.name}`);if(type==='encounter')announce(`${data.name} · ${data.desc}`);if(type==='bossPhase')announce(`灰燼守衛 · ${data.name}階段`);if(type==='pause')showPause();if(type==='resume')overlay.innerHTML='';if(type==='boss'){announce('灰燼守衛，已經甦醒');$('obj1').className='done';$('obj2').className='active';$('bossHud').classList.remove('hidden')}if(type==='end')showEnd(data)}
game=new Game({onEvent});const renderer=new Renderer($('game'));input=new Input(()=>game.pause(),()=>{audio.unlock();game.dash()});
const arena=document.querySelector('.arena'),encounterLayer=document.createElement('div'),encounterEls=new Map();
if(getComputedStyle(arena).position==='static')arena.style.position='relative';Object.assign(encounterLayer.style,{position:'absolute',inset:'0',pointerEvents:'none',zIndex:'4',overflow:'hidden'});encounterLayer.setAttribute('aria-hidden','true');arena.appendChild(encounterLayer);
function encounterElement(encounter){let el=encounterEls.get(encounter.id);if(el)return el;const view=getEncounterPresentation(encounter);el=document.createElement('div');el.innerHTML=`<span>${view.glyph}</span><small>${view.name}</small>`;Object.assign(el.style,{position:'absolute',width:'34px',height:'34px',borderRadius:'50%',border:`1px solid ${view.accent}`,background:'rgba(14,24,18,.88)',boxShadow:`0 0 18px ${view.accent}66`,display:'grid',placeItems:'center',fontSize:'18px',color:view.accent,willChange:'transform,left,top'});const label=el.querySelector('small');Object.assign(label.style,{position:'absolute',top:'38px',left:'50%',transform:'translateX(-50%)',whiteSpace:'nowrap',padding:'3px 6px',borderRadius:'4px',background:'rgba(8,16,12,.8)',fontSize:'10px',letterSpacing:'.06em',color:'#e5dfc9'});encounterLayer.appendChild(el);encounterEls.set(encounter.id,el);return el}
function syncEncounterMarkers(clock){if(game.state==='menu'){encounterLayer.style.display='none';return}encounterLayer.style.display='block';const ar=arena.getBoundingClientRect(),cr=renderer.canvas.getBoundingClientRect(),z=renderer.zoom||1,cam=renderer.camera,active=new Set(),w=cr.width,h=cr.height,ox=cr.left-ar.left,oy=cr.top-ar.top;for(const encounter of game.encounters){if(encounter.resolved)continue;active.add(encounter.id);const el=encounterElement(encounter),rawX=w/2+(encounter.x-cam.x)*z,rawY=h/2+(encounter.y-cam.y)*z,inside=rawX>32&&rawX<w-32&&rawY>52&&rawY<h-46,x=Math.max(28,Math.min(w-28,rawX)),y=Math.max(48,Math.min(h-42,rawY)),near=Math.hypot(encounter.x-game.player.x,encounter.y-game.player.y)<250,pulse=1+Math.sin(clock*3+encounter.x*.01)*.055;el.style.left=`${ox+x}px`;el.style.top=`${oy+y}px`;el.style.transform=`translate(-50%,-50%) scale(${pulse})`;el.style.opacity=inside?'1':'.78';el.querySelector('small').style.display=inside&&near&&w>620?'block':'none'}for(const [id,el] of encounterEls){if(active.has(id))continue;el.remove();encounterEls.delete(id)}}
function start(){audio.unlock();input.reset();clearTimeout(announceTimeout);$('announcement').style.opacity=0;game.reset();renderer.camera={x:1200,y:1200};overlay.innerHTML='';$('obj1').className='active';$('obj2').className='';$('obj3').className='';$('bossHud').classList.add('hidden');$('seedText').textContent=`世界種子 ${game.seed.toString(16).toUpperCase()}`;updateSkills();announce('探索荒野、收集靈晶，尋找散落的祭壇與靈匣')}
function showStart(){modal(`<div class="start-screen"><div class="sigil">✧</div><span class="eyebrow">THE FIRE STILL REMAINS</span><h1>EMBERFALL</h1><h2>燼 境</h2><p>踏入不斷變化的荒野，以餘燼化為法術。<br>活下來，直到遠古守衛甦醒。</p><button class="primary" id="start">開始遠征 <span aria-hidden="true">↗</span></button><div class="start-meta"><span>✧ 隨機技能組合</span><span>◷ 約 4–6 分鐘一局</span></div>${best?`<p style="font-size:11px;margin-top:18px">最長存活 ${format(best)}</p>`:''}</div>`);$('start').onclick=start}
function showChoices(choices){modal(`<div class="modal"><span class="eyebrow">LEVEL ${game.player.level} / 選擇你的道路</span><h2>讓餘燼，化為力量。</h2><p>選擇一項強化 · 本次升級已回復 10 點生命</p><div class="choices">${choices.map(({skill,rarity},i)=>`<button class="choice ${rarity}" data-choice="${i}"><span class="rarity">${RARITIES[rarity].name} / ${rarity.toUpperCase()}</span><span class="glyph">${skill.icon}</span><strong>${skill.name}</strong><p>${skill.desc(RARITIES[rarity].mult)}</p><span class="select">選擇 ${i+1} ↗</span></button>`).join('')}</div></div>`);overlay.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>game.choose(Number(b.dataset.choice)))}
function showPause(){modal(`<div class="modal"><span class="eyebrow">TAKE A BREATH</span><h2>火焰，為你停留。</h2><p>遠征已暫停。<br>移動：WASD / 方向鍵 / 觸控搖桿<br>衝刺：空白鍵 / 右下按鈕，冷卻 3 秒。</p><div class="modal-actions"><button id="resume" class="primary">繼續遠征</button><button id="restart" class="secondary">重新開始</button></div></div>`);$('resume').onclick=()=>game.pause();$('restart').onclick=start}
function showEnd(won){best=Math.max(best,game.time);try{localStorage.setItem('emberfall-best',best)}catch{}if(won){$('obj1').className='done';$('obj2').className='done';$('obj3').className='done';$('bossHud').classList.add('hidden')}modal(`<div class="modal"><div class="sigil">${won?'✺':'✧'}</div><span class="eyebrow">${won?'EXPEDITION COMPLETE':'THE EMBERS REMAIN'}</span><h2>${won?'火光，再度重燃。':'旅途尚未結束。'}</h2><p>${won?'灰燼守衛已倒下。這片荒野記住了你的名字。':'你的餘燼將化為下一次旅途的火種。'}</p><div class="results"><div><strong>${format(game.time)}</strong><span>存活時間</span></div><div><strong>${game.kills}</strong><span>擊敗敵人</span></div><div><strong>${game.player.level}</strong><span>最終等級</span></div></div><div class="modal-actions"><button id="again" class="primary">再次遠征 ↗</button></div></div>`);$('again').onclick=start}
function updateSkills(){const items=Object.values(game.owned);$('skillCount').textContent=items.length+1;$('skillList').innerHTML=`<div class="skill-row"><span class="skill-icon">✷</span><div><strong>初始火球</strong><small>自動施放 · 爆炸傷害</small></div><span>×${game.player.projectiles}</span></div>`+items.map(({skill,rarity,count})=>`<div class="skill-row"><span class="skill-icon" style="border-color:${RARITIES[rarity].color};color:${RARITIES[rarity].color}">${skill.icon}</span><div><strong>${skill.name}</strong><small>${RARITIES[rarity].name}</small></div><span>×${count}</span></div>`).join('')}
function hud(){const p=game.player;$('hpText').textContent=`${Math.ceil(p.hp)} / ${Math.round(p.maxHp)}`;$('hpFill').style.width=`${p.hp/p.maxHp*100}%`;$('levelText').textContent=`LV. ${String(p.level).padStart(2,'0')}`;$('xpFill').style.width=`${Math.min(100,p.xp/p.nextXp*100)}%`;$('xpText').textContent=`${p.xp} / ${p.nextXp}`;$('timer').textContent=format(game.time);$('killText').textContent=`擊敗 ${game.kills}`;const bossStage=game.boss?.bossStage||1,bossPhase=bossStage===3?'末焰暴走':bossStage===2?'焚心狂怒':'守衛甦醒';$('phaseText').textContent=game.bossSpawned?`終章 · ${bossPhase}`:game.time>90?'第二章 · 暗潮湧動':'第一章 · 甦醒之森';$('dashState').textContent=p.dashCooldown>0?`衝刺 · ${p.dashCooldown.toFixed(1)}s`:'SPACE · 衝刺就緒';$('dashTouch').style.opacity=p.dashCooldown>0?'.4':'1';if(game.boss){$('bossHp').textContent=`${Math.max(0,Math.ceil(game.boss.hp))} / ${game.boss.maxHp}`;$('bossFill').style.width=`${Math.max(0,game.boss.hp/game.boss.maxHp*100)}%`}}
$('pause').onclick=()=>game.pause();$('sound').onclick=()=>{$('sound').textContent=audio.toggle()?'♫':'♪̸';$('sound').setAttribute('aria-label',audio.enabled?'關閉音效':'開啟音效')};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.state==='playing')game.pause();input.reset()});window.addEventListener('blur',()=>{if(game.state==='playing')game.pause()});window.addEventListener('keydown',e=>{if(game.state==='levelup'&&['1','2','3'].includes(e.key))game.choose(Number(e.key)-1)});
let previous=performance.now(),accumulator=0,uiClock=0;function frame(now){const dt=Math.min((now-previous)/1000,.1);previous=now;if(game.state==='playing'){accumulator+=dt;let steps=0;while(accumulator>=1/60&&steps<6){game.step(1/60,input.direction());accumulator-=1/60;steps++}}else accumulator=0;renderer.draw(game,now/1000);syncEncounterMarkers(now/1000);uiClock+=dt;if(uiClock>.1){hud();uiClock=0}requestAnimationFrame(frame)}
showStart();updateSkills();hud();requestAnimationFrame(frame);
